32| function chooseSurfaceDetail(biome, climate) {
33|   if (biome === 'ocean') return climate.elevation < 0.24 ? 'deep_water' : 'shallow_water';
34|   if (biome === 'beach') return climate.moisture > 0.5 ? 'wet_sand' : 'dry_sand';
35|   if (biome === 'mystic') return 'aether_bloom';
36|   if (biome === 'forest' || biome === 'dense_forest' || biome === 'taiga' || biome === 'tropical_forest') return 'leaf_litter';
37|   if (biome === 'mountains' || biome === 'hills' || biome === 'volcanic') return 'stone_scatter';
38|   if (biome === 'swamp') return 'mud_pools';
39|   if (biome === 'tundra' || biome === 'arctic') return 'snow_drift';
40|   return 'ground_cover';
