4| // Domain-warped ridge noise — creates sharp ridge lines and valleys.
5| // Returns value in [0,1] where 0.5 = flat, >0.5 = ridge, <0.5 = valley.
6| function ridgeNoise(x, y, scale, salt, seed) {
7|   // Sample two smooth noise layers offset by 90 degrees
8|   const n1 = fbm(x, y, salt, seed, scale, 3);
9|   const n2 = fbm(x + 300, y + 300, salt + 100, seed, scale, 3);
10|   // Ridge = 1 - |2n-1| (sharp peaks at n=0.5)
11|   const ridge = 1 - Math.abs(n1 * 2 - 1);
12|   const valley = 1 - Math.abs(n2 * 2 - 1);
13|   // Blend ridge and valley for varied terrain
14|   return ridge * 0.6 + valley * 0.4;
15| }
16| 
17| // Domain warp — distorts coordinates through noise for organic shapes
18| function warpX(x, y, seed, strength = 40) {
19|   return x + smoothNoise(x, y, 300, 500, seed) * strength - strength * 0.5;
20| }
21| function warpY(x, y, seed, strength = 40) {
22|   return y + smoothNoise(x + 700, y + 700, 300, 600, seed) * strength - strength * 0.5;
23| }
24| 
25| // Terrain shaper — takes raw 0-1 elevation and remaps it into dramatic landforms.
26| // Returns { elevation: 0-1, ridgeStrength: 0-1, isPeak: 0-1, valleyDepth: 0-1 }
27| export function shapeTerrain(wx, wy, rawElevation) {
28|   const seed = getWorldSeed();
29| 
30|   // Warp coordinates for organic shapes (Grand Canyon finger-lake style)
31|   const wxW = warpX(wx, wy, seed, 60);
32|   const wyW = warpY(wx, wy, seed, 60);
33| 
34|   // Ridge network at medium scale
35|   const ridge = ridgeNoise(wxW, wyW, 220, 700, seed);
36| 
37|   // Large-scale mountain ridges
38|   const mountainRidge = ridgeNoise(wxW, wyW, 500, 800, seed);
39| 
40|   // Micro-detail for texture within plateaus
41|   const micro = fbm(wx, wy, 500, seed, 60, 4);
42| 
43|   // Combine: base elevation defines overall height, ridges create structure
44|   // rawElevation: 0-1 continental scale
45|   // ridge: 0-1 ridge network (peaked at 1)
46|   // mountainRidge: 0-1 large ridges
47| 
48|   let shaped;
49| 
50|   if (rawElevation < 0.35) {
51|     // Lowlands / water — keep mostly flat with subtle valleys
52|     shaped = rawElevation * 0.8 + ridge * 0.15 - micro * 0.05;
53|   } else if (rawElevation < 0.55) {
