const { fbm, rand2, smoothNoise, hash, lerp } = (function() {
  function hash(n) { n = (n ^ 61) ^ (n >>> 16); n = Math.imul(n, 9); n = n ^ (n >>> 4); n = Math.imul(n, 0x27d4eb2d); n = n ^ (n >>> 15); return (n >>> 0) / 4294967295; }
  function rand2(x, y, salt = 0, seed = 42) { return hash(Math.imul(x, 374761393) ^ Math.imul(y, 668265263) ^ Math.imul(seed + salt, 1442695041)); }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function smoothNoise(x, y, scale, salt, seed = 42) {
    const fx = x / scale, fy = y / scale;
    const x0 = Math.floor(fx), y0 = Math.floor(fy);
    const tx = fx - x0, ty = fy - y0;
    const sx = tx * tx * (3 - 2 * tx), sy = ty * ty * (3 - 2 * ty);
    return lerp(lerp(rand2(x0, y0, salt, seed), rand2(x0 + 1, y0, salt, seed), sx), lerp(rand2(x0, y0 + 1, salt, seed), rand2(x0 + 1, y0 + 1, salt, seed), sx), sy);
  }
  function fbm(x, y, salt, seed = 42, baseScale = 180, octaves = 5) {
    let value = 0, amplitude = 0.5, scale = baseScale, norm = 0;
    for (let o = 0; o < octaves; o++) { value += smoothNoise(x, y, scale, salt + o * 31, seed) * amplitude; norm += amplitude; scale *= 0.5; amplitude *= 0.5; }
    return norm > 0 ? value / norm : value;
  }
  function clamp01(v) { return Math.max(0, Math.min(1, v)); }
  function warpX(x, y, seed, strength = 40) { return x + smoothNoise(x, y, 300, 500, seed) * strength - strength * 0.5; }
  function warpY(x, y, seed, strength = 40) { return y + smoothNoise(x + 700, y + 700, 300, 600, seed) * strength - strength * 0.5; }
  function ridgeNoise(x, y, scale, salt, seed) {
    const n1 = fbm(x, y, salt, seed, scale, 3);
    const n2 = fbm(x + 300, y + 300, salt + 100, seed, scale, 3);
