25|     const key = chunkKey(cx, cy);
26|     const ready = this.provider.getReady(cx, cy);
27|     if (ready) {
28|       this.chunks.set(key, ready);
29|       return ready;
30|     }
31|     this.provider.request(cx, cy);
32|     // Never synchronously compile chunks on the main thread while walking.
33|     // Return a cached copy if we have one; otherwise null and callers should
34|     // wait for the worker result.
35|     return this.chunks.get(key) ?? null;
36|   }
37| 
38|   getIfReady(cx, cy) {
39|     const key = chunkKey(cx, cy);
40|     const ready = this.provider.getReady(cx, cy);
41|     if (ready) this.chunks.set(key, ready);
42|     return ready ?? this.chunks.get(key) ?? null;
43|   }
44| 
45|   getVisible(cx, cy) {
46|     const key = chunkKey(cx, cy);
47|     const ready = this.provider.getReady(cx, cy);
48|     if (ready) {
49|       this.chunks.set(key, ready);
50|       return ready;
51|     }
52|     this.provider.request(cx, cy);
53|     return this.chunks.get(key) ?? null;
54|   }
55| 
56|   streamAround(wx, wy) {
57|     const pcx = floorDiv(wx, WORLD.chunkSize);
58|     const pcy = floorDiv(wy, WORLD.chunkSize);
59|     const currentReady = this.getIfReady(pcx, pcy);
60|     if (currentReady) this.lastPlayerChunk = { cx: pcx, cy: pcy };
61| 
62|     const jobs = [];
63|     const addJobsAround = (ccx, ccy, extraPriority = 0) => {
64|       for (let cy = ccy - WORLD.loadRadius; cy <= ccy + WORLD.loadRadius; cy++) {
65|         for (let cx = ccx - WORLD.loadRadius; cx <= ccx + WORLD.loadRadius; cx++) {
66|           jobs.push({ cx, cy, d: Math.abs(cx - ccx) + Math.abs(cy - ccy) + extraPriority });
67|         }
68|       }
69|     };
70|     addJobsAround(pcx, pcy, 0);
71|     // Predictive prefetch: when near a chunk edge, start streaming the next
72|     // chunk neighborhood before the player crosses the boundary.
73|     const lx = ((Math.floor(wx) % WORLD.chunkSize) + WORLD.chunkSize) % WORLD.chunkSize;
74|     const ly = ((Math.floor(wy) % WORLD.chunkSize) + WORLD.chunkSize) % WORLD.chunkSize;
75|     const margin = Math.max(24, Math.floor(WORLD.chunkSize * 0.50));
76|     if (lx < margin) addJobsAround(pcx - 1, pcy, 3);
77|     if (lx >= WORLD.chunkSize - margin) addJobsAround(pcx + 1, pcy, 3);
78|     if (ly < margin) addJobsAround(pcx, pcy - 1, 3);
79|     if (ly >= WORLD.chunkSize - margin) addJobsAround(pcx, pcy + 1, 3);
80|     jobs.sort((a, b) => a.d - b.d);
81|     const seenJobs = new Set();
82|     for (const job of jobs) {
83|       const key = chunkKey(job.cx, job.cy);
84|       if (seenJobs.has(key)) continue;
85|       seenJobs.add(key);
86|       const ready = this.provider.getReady(job.cx, job.cy);
87|       if (ready) this.chunks.set(key, ready);
88|       else this.provider.request(job.cx, job.cy, job.d);
89|     }

