function smoothNoise(x,y,scale,salt,seed){seed=seed||42;var fx=x/scale,fy=y/scale,x0=Math.floor(fx),y0=Math.floor(fy),tx=fx-x0,ty=fy-y0,sx=tx*tx*(3-2*tx),sy=ty*ty*(3-2*ty);return lerp(lerp(rand2(x0,y0,salt,seed),rand2(x0+1,y0,salt,seed),sx),lerp(rand2(x0,y0+1,salt,seed),rand2(x0+1,y0+1,salt,seed),sx),sy)}
