else if(localStep>0.045&&e>0.48)form='step';
else if(e>0.56)form='hillside';

console.log('elev:',e);
console.log('plateauLevel:',pLevel,'plateauDelta:',pDelta);
console.log('localStep:',localStep,'slope:',slope);
console.log('ridgeSignal:',ridgeSignal,'valleySignal:',valleySignal,'convexity:',convexity);
console.log('form:',form);
console.log('');
if(form==='cliff')console.log('BLOCKED: cliff');
else if(localStep>0.10)console.log('BLOCKED: localStep '+localStep+' > 0.10');
else if(slope>0.16)console.log('BLOCKED: slope '+slope+' > 0.16');
else console.log('canEnterTile: PASS');
"

